import * as T from './vendor/three.js';
export function forestSampler(meta,data){return(x,z)=>{const u=T.MathUtils.clamp((x-meta.minX)/(meta.maxX-meta.minX)*(meta.width-1),0,meta.width-1.001),v=T.MathUtils.clamp((z-meta.minZ)/(meta.maxZ-meta.minZ)*(meta.height-1),0,meta.height-1.001),i=Math.floor(u),j=Math.floor(v),du=u-i,dv=v-j,k=j*meta.width+i;return(data[k]*(1-du)*(1-dv)+data[k+1]*du*(1-dv)+data[k+meta.width]*(1-du)*dv+data[k+meta.width+1]*du*dv)/255}}
export function addHillsideForest(scene,{density,ground,network,freeBuildings,tunnels,foliage}){
 let seed=60127;const rand=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646};const groups=new Map(),spacing=14,palette=['#c1d2ad','#d3d8ba','#b7c9ad','#d9ddc6','#b8c8b4','#ccd2b9'];
 for(let gx=-3450;gx<3450;gx+=spacing)for(let gz=-3450;gz<3450;gz+=spacing){const x=gx+(rand()-.5)*spacing*.6,z=gz+(rand()-.5)*spacing*.6,coverage=density(x,z);if(coverage<.23||rand()>Math.min(1,coverage*1.3))continue;const radius=6.8+rand()*3.2,hit=network.at(x,z);if(hit){const path=['footway','path','track','cycleway','bridleway','steps'].includes(hit.r.type);if(hit.d<hit.r.width/2+(path?1.2:radius+1.5))continue}let clear=true;for(const[dx,dz]of [[0,0],[radius,0],[-radius,0],[0,radius],[0,-radius]])if(!freeBuildings(x+dx,z+dz)||tunnels?.clearPortal(x+dx,z+dz)){clear=false;break}if(!clear)continue;const y=ground(x,z),height=8+rand()*8,key=Math.floor(x/512)+','+Math.floor(z/512);if(!groups.has(key))groups.set(key,[]);groups.get(key).push({x,y,z,radius,height,color:palette[Math.floor(rand()*palette.length)],rotation:rand()*Math.PI*2,shrub:rand()<.34})}
 const trunkGeo=new T.CylinderGeometry(.25,.48,1,6),trunkMaterial=new T.MeshLambertMaterial({color:'#776b59'}),dummy=new T.Object3D(),color=new T.Color(),chunks=[];let crowns=0,understory=0;
 for(const trees of groups.values()){const leaves=foliage.mesh(trees.length,crowns%4),trunks=new T.InstancedMesh(trunkGeo,trunkMaterial,trees.length),shrubs=foliage.mesh(trees.filter(t=>t.shrub).length,2);let n=0,sx=0,sz=0;for(let i=0;i<trees.length;i++){const t=trees[i];sx+=t.x;sz+=t.z;dummy.position.set(t.x,t.y+t.height*.66,t.z);dummy.rotation.set(0,t.rotation,0);dummy.scale.set(t.radius,t.height*.37,t.radius*(.85+(i%4)*.07));dummy.updateMatrix();leaves.setMatrixAt(i,dummy.matrix);leaves.setColorAt(i,color.set(t.color));dummy.position.y=t.y+t.height*.34;dummy.scale.set(1,t.height*.68,1);dummy.updateMatrix();trunks.setMatrixAt(i,dummy.matrix);if(t.shrub){dummy.position.set(t.x+Math.cos(t.rotation)*3,t.y+1.5,t.z+Math.sin(t.rotation)*3);dummy.scale.set(2.8,1.8,2.5);dummy.updateMatrix();shrubs.setMatrixAt(n,dummy.matrix);shrubs.setColorAt(n++,color.set(t.color).multiplyScalar(.88))}}for(const m of [leaves,trunks,shrubs]){m.instanceMatrix.needsUpdate=true;if(m.instanceColor)m.instanceColor.needsUpdate=true;m.computeBoundingSphere();scene.add(m)}chunks.push({trunks,shrubs,x:sx/trees.length,z:sz/trees.length});crowns+=trees.length;understory+=n}
 function update(camera){foliage.update();const low=camera.y-ground(camera.x,camera.z)<140;for(const chunk of chunks){const d=Math.hypot(camera.x-chunk.x,camera.z-chunk.z);chunk.trunks.visible=low&&d<850;chunk.shrubs.visible=low&&d<650}}
 return{crowns,understory,chunks:chunks.length,update};
}
